<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigWellcomeEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWellcomeEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withWellcomeEmail,
 * getWellcomeEmail/wellcomeEmail accessors, and isWellcomeEmailChanged with/without original.
 */
class TenantConfigWellcomeEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWellcomeEmail creates a new instance with the WellcomeEmail set
     * from a string value, and getWellcomeEmail returns the primitive string.
     */
    public function testWithWellcomeEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWellcomeEmailAccessorUnitTest();

        // Act
        $result = $holder->withWellcomeEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getWellcomeEmail());
    }
    /**
     * Asserts that withwellcomeEmail has access to the value object
     * from a string value, and getWellcomeEmail returns the primitive string.
     */
    public function testWithWellcomeEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWellcomeEmailAccessorUnitTest();

        // Act
        $result = $holder->withWellcomeEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->wellcomeEmail()->value());
    }
    public function testChangedWellcomeEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWellcomeEmailAccessorUnitTest();
        $original = $holder->withWellcomeEmail('one');
        $same = $holder->withWellcomeEmail('one');
        $modified = $holder->withWellcomeEmail('other');

        // Act
        $unchanged = $holder->isWellcomeEmailChanged();
        $withSame = $original->isWellcomeEmailChanged($same);
        $withDiferent = $original->isWellcomeEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigWellcomeEmailAccessorUnitTest
{
    use TenantConfigWellcomeEmailAccessor;
}
